using Microsoft.EntityFrameworkCore;using RetailShop.Application.Common;using RetailShop.Application.Finance;using RetailShop.Domain.Finance;using RetailShop.Infrastructure.Persistence;
namespace RetailShop.Infrastructure.Finance;
internal sealed class FinanceSetupService(RetailShopDbContext db,IJournalPostingService posting):IFinanceSetupService
{
 public async Task<OpeningPositionItem> AssessOpeningAsync(CancellationToken ct=default){var qty=await db.StockBalances.SumAsync(x=>(decimal?)x.AvailableQuantity,ct)??0;var value=await db.StockBalances.Join(db.Products,s=>s.ProductId,p=>p.Id,(s,p)=>s.AvailableQuantity*p.AverageCost).SumAsync(x=>(decimal?)x,ct)??0;var ar=await db.CustomerLedgerEntries.SumAsync(x=>(decimal?)(x.Debit-x.Credit),ct)??0;var ap=await db.SupplierLedgerEntries.SumAsync(x=>(decimal?)(x.Credit-x.Debit),ct)??0;var dr=await db.JournalLines.SumAsync(x=>(decimal?)x.Debit,ct)??0;var cr=await db.JournalLines.SumAsync(x=>(decimal?)x.Credit,ct)??0;return new(qty,FinanceAmount.Round(value),FinanceAmount.Round(ar),FinanceAmount.Round(ap),dr,cr,value==0&&ar==0&&ap==0);}
 public async Task<FinanceReadinessItem> ReadinessAsync(DateOnly cutover,CancellationToken ct=default){var p=await AssessOpeningAsync(ct);var accounts=await db.Accounts.CountAsync(x=>x.IsSystemControlled&&x.IsActive,ct)>=18;var system=await db.AccountMappings.CountAsync(x=>x.Type==AccountMappingType.System&&x.IsActive,ct)>=18;var payments=!await db.PaymentMethods.AnyAsync(x=>x.IsActive&&!db.AccountMappings.Any(m=>m.PaymentMethodId==x.Id&&m.IsActive),ct);var expenses=!await db.ExpenseCategories.AnyAsync(x=>x.IsActive&&!db.AccountMappings.Any(m=>m.ExpenseCategoryId==x.Id&&m.IsActive),ct);var financial=await db.FinancialAccounts.AnyAsync(x=>x.IsActive,ct);var period=await db.FiscalPeriods.AnyAsync(x=>x.StartDate<=cutover&&x.EndDate>=cutover&&x.Status==FiscalPeriodStatus.Open,ct);var activation=await db.FinanceActivations.SingleAsync(ct);var opening=activation.OpeningBalancesApproved;var recon=activation.ReconciliationReady;var balanced=p.JournalDebits==p.JournalCredits;var blockers=new List<string>();if(!accounts)blockers.Add("Chart of Accounts is incomplete.");if(!system)blockers.Add("Required system mappings are incomplete.");if(!payments)blockers.Add("Active payment methods require mappings.");if(!expenses)blockers.Add("Active expense categories require mappings.");if(!financial)blockers.Add("At least one financial account is required.");if(!period)blockers.Add("Cutover date requires an open fiscal period.");if(!opening)blockers.Add("Opening balances are not approved and posted.");if(!recon)blockers.Add("Operational balances are not reconciled.");if(!balanced)blockers.Add("The General Ledger is unbalanced.");return new(accounts,system,payments,expenses,financial,period,opening,recon,balanced,blockers.Count==0,blockers,p);}
 public async Task<OperationResult<Guid>> SaveOpeningBatchAsync(OpeningBatchRequest r,Guid by,CancellationToken ct=default){try{var x=new OpeningBalanceBatch(r.BusinessDate,r.Description,by);x.ReplaceLines(r.Lines.Select(l=>new OpeningBalanceLine(l.AccountId,l.Debit,l.Credit,l.ReconciliationType,l.ReconciliationId)));db.Add(x);await db.SaveChangesAsync(ct);return OperationResult<Guid>.Success(x.Id);}catch(Exception e)when(e is ArgumentException or InvalidOperationException){return OperationResult<Guid>.Failure(e.Message);}}
 public async Task<OperationResult<bool>> ApproveOpeningBatchAsync(Guid id,Guid by,CancellationToken ct=default){var x=await db.OpeningBalanceBatches.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return OperationResult<bool>.Failure("Opening batch not found.");try{x.Approve(by);await db.SaveChangesAsync(ct);return OperationResult<bool>.Success(true);}catch(InvalidOperationException e){return OperationResult<bool>.Failure(e.Message);}}
 public async Task<OperationResult<JournalItem>> PostOpeningBatchAsync(Guid id,Guid by,CancellationToken ct=default){var x=await db.OpeningBalanceBatches.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==id,ct);if(x is null||x.Status!=OpeningBalanceBatchStatus.Approved)return OperationResult<JournalItem>.Failure("Opening batch is not approved.");var result=await posting.PostAsync(new(x.BusinessDate,"OpeningBalanceBatch",x.Id,FinancePostingKinds.OpeningBalance,x.Description,x.Lines.Select(l=>new JournalLineRequest(l.AccountId,l.Debit,l.Credit,l.ReconciliationType)).ToArray()),by,ct);if(result.Succeeded){x.MarkPosted(result.Value!.Id);var a=await db.FinanceActivations.SingleAsync(ct);a.RecordReadiness(true,true,a.ReconciliationReady);db.Add(new FinanceActivationAudit("OpeningPosted",$"Opening batch {x.Id} posted.",by));await db.SaveChangesAsync(ct);}return result;}
 public async Task<OperationResult<bool>> ActivateAsync(DateOnly cutover,Guid by,CancellationToken ct=default){var ready=await ReadinessAsync(cutover,ct);if(!ready.CanActivate)return OperationResult<bool>.Failure(ready.Blockers);var a=await db.FinanceActivations.SingleAsync(ct);a.Activate(cutover,by);db.Add(new FinanceActivationAudit("Activated",$"Finance activated from {cutover:yyyy-MM-dd}.",by));await db.SaveChangesAsync(ct);return OperationResult<bool>.Success(true);}
}
